<script>
import {onMount} from 'svelte';import {snapshot,clock,events,history,errors,loadResource,navigate} from '../state.js';import {fresh,bytes,formatMS,date,time,clusterState} from '../lib.js';import Icon from '../components/Icon.svelte';import Badge from '../components/Badge.svelte';import NodeTable from '../components/NodeTable.svelte';import Topology from '../components/Topology.svelte';import Chart from '../components/Chart.svelte';
let coverageOpen=false;$: s=$snapshot;$: cov=s?.coverage||{};$: active=(s?.incidents||[]).filter(i=>!i.resolved_at);$: lat=(s?.nodes||[]).filter(n=>fresh(n.cql,$clock,s.stale_after_seconds)&&n.cql.ok).map(n=>n.cql.latency/1e6);$: avg=lat.length?lat.reduce((a,b)=>a+b,0)/lat.length:null;$: total=s?.nodes?.length&&s.nodes.every(n=>n.load_known&&n.metadata_known)?s.nodes.reduce((a,n)=>a+n.load_bytes,0):null;

</script>
{#if s}
<div class="kpis"><div class="kpi"><span><Icon name="nodes" size={16}/> Scyllaメンバー</span><strong>{cov.discovered_nodes??'—'}<small>/ {cov.expected_nodes??'—'}</small></strong><div>到達性 {cov.reachable_nodes??'—'} 台 · {bytes(total)}</div></div><div class="kpi"><span><Icon name="topology" size={16}/> 観測エージェント</span><strong>{cov.agents_ready??'—'}<small>/ {s.nodes.length}</small></strong><div>{cov.observed_directions??0} / {cov.expected_directions??0} 方向の観測</div></div><button class="kpi clickable" onclick={()=>navigate('alerts')}><span><Icon name="alerts" size={16}/> アクティブアラート</span><strong class:critical={active.length>0}>{active.length}</strong><div>この観測元で確定した異常</div></button><div class="kpi"><span><Icon name="bolt" size={16}/> CQLプロトコル応答</span><strong class="metric-size">{formatMS(avg)}</strong><div>この観測元からの平均 · OPTIONS</div></div></div>
{#if s.warnings.length||!s.discovery.ok||cov.agents_ready<s.nodes.length}<details class="coverage-bar" bind:open={coverageOpen}><summary><Icon name="info" size={14}/><span>{!s.discovery.ok?'クラスタ一覧を取得できていません':cov.agents_ready<s.nodes.length?`分散観測 ${cov.agents_ready}/${s.nodes.length} 台 · 未観測の方向があります`:`確認事項 ${s.warnings.length}件`}</span><span class="quiet">詳細</span></summary><div>{#each s.warnings as w}<p>{w}</p>{/each}{#if !s.discovery.ok}<p>{s.discovery.message}</p>{/if}{#if cov.agents_ready<s.nodes.length}<p>DBメンバーと観測エージェントは別です。各ノードにScopeを配置し、同じcluster_tokenを設定すると方向別の結果を共有します。</p>{/if}</div></details>{/if}
<div class="dashboard-grid"><section class="panel topology-panel"><header class="panel-header"><h2>クラスタ接続図 <span class="muted-badge">{s.nodes.length} nodes</span></h2><button class="link-button" onclick={()=>navigate('topology')}>詳細を開く <Icon name="external" size={13}/></button></header><Topology compact/></section><aside class="dashboard-side"><section class="panel"><header class="panel-header"><h2>アラート</h2><button class="link-button" onclick={()=>navigate('alerts')}>すべて <Icon name="chevron" size={13}/></button></header>{#if active.length}<div class="alert-mini">{#each active.slice(0,2) as i (i.id)}<button onclick={()=>navigate('alerts')}><Badge state={i.severity}/><p>{i.message}</p></button>{/each}</div>{:else}<div class="clear-state"><span class="clear-icon"><Icon name="check" size={20}/></span><div><strong>確定したアラートなし</strong><p>未観測の状態は正常に含めません</p></div></div>{/if}</section><section class="panel"><header class="panel-header"><h2>最近のイベント</h2><button class="link-button" onclick={()=>navigate('events')}>履歴 <Icon name="chevron" size={13}/></button></header><div class="timeline">{#each $events.slice(0,4) as ev (ev.id)}<div class="timeline-row"><time title={date(ev.time)}>{time(ev.time)}</time><span class="dot {ev.severity==='critical'?'critical':ev.severity==='warning'?'warning':'healthy'}"></span><p>{ev.message}</p></div>{:else}<p class="quiet">イベントはまだありません</p>{/each}</div></section></aside></div>
<section class="panel"><header class="panel-header"><h2>ノードの状態</h2><button class="link-button" onclick={()=>navigate('nodes')}>ノード一覧 <Icon name="chevron" size={13}/></button></header><NodeTable nodes={s.nodes}/></section>
<div class="summary-footer"><span><span class="dot live"></span> {s.local_node_name||s.local_node} からの観測</span><span>SQLite履歴 · {date(s.generated_at)}</span><button class="link-button" onclick={()=>navigate('metrics')}>履歴グラフを開く <Icon name="arrow" size={13}/></button></div>
{:else}<div class="empty"><Icon name="nodes" size={32}/><h2>最初の観測を待っています</h2><p>接続できない場合でも、状態を正常として表示しません。</p></div>{/if}
